function wordRearrangement(words) {
  return words.map(word => {
    const [left, right] = word;
    const leftArr = left.split('');
    const rightArr = right.split('');
    const leftSet = new Set(leftArr);
    const rightSet = new Set(rightArr);
    if (leftArr.length !== rightArr.length) return false;
    if (leftSet.size !== rightSet.size) return false;
    for (const letter of leftSet) {
      if (leftArr.filter(letter => letter === letter).length !== rightArr.filter(letter => letter === letter).length) return false;
    }
    return true;
  });
}

