  let hash = {};
  let max = 0;
  for (let i = 0; i < arr.length; i++) {
    hash[arr[i]] = true;
  }
  for (let i = 0; i < arr.length; i++) {
    let count = 1;
    let left = arr[i] - 1;
    let right = arr[i] + 1;
    while (hash[left]) {
      hash[left] = false;
      count++;
      left--;
    }
    while (hash[right]) {
      hash[right] = false;
      count++;
      right++;
    }
    max = Math.max(max, count);
  }
  return max;
}

