    public static int lcs(String a, String b) {
        int[][] lcs = new int[a.length()+1][b.length()+1];
        for(int i=0; i<=a.length(); i++) {
            for(int j=0; j<=b.length(); j++) {
                if(i==0 || j==0) {
                    lcs[i][j] = 0;
