public class MinimumLengthOfRope {
    public static void main(String[] args) {
        int[][] field = {{1, 0, 0}, {1, 1, 0}, {1, 1, 1}};
        System.out.println(minimumLengthOfRope(field));
    }

    private static int minimumLengthOfRope(int[][] field) {
        int rows = field.length;
        int cols = field[0].length;
        int[][] dp = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (field[i][j] == 1) {
                    dp[i][j] = 1;
                    if (i > 0) {
                        dp[i][j] += dp[i - 1][j];
                    }
                    if (j > 0) {
                        dp[i][j] += dp[i][j - 1];
                    }
                }
            }
        }
        return dp[rows - 1][cols - 1] - 1;
    }
}

