#include <string>
#include <algorithm>
#include <unordered_map>
using namespace std;

vector<int> startingIndices(string s) {
    vector<int> start;
    unordered_map<char, int> m;
    for (int i = 0; i < s.length(); i++) {
        if (m.find(s[i]) == m.end()) {
            m[s[i]] = i;
            start.push_back(i);
        }
    }
    return start;
}

vector<int> endingIndices(string s) {
    vector<int> end;
    unordered_map<char, int> m;
    for (int i = s.length() - 1; i >= 0; i--) {
        if (m.find(s[i]) == m.end()) {
            m[s[i]] = i;
            end.push_back(i);
        }
    }
    return end;
}

int main() {
    string s = "abba";
    vector<int> start = startingIndices(s);
    vector<int> end = endingIndices(s);
    for (int i = 0; i < start.size(); i++) {
        cout << start[i] << " ";
    }
    cout << endl;
    for (int i = 0; i < end.size(); i++) {
        cout << end[i] << " ";
    }
    return 0;
}

