function longestConsecutiveSequence(array) {
  // your code goes here
  let hash = {};
  let max = 0;
  for (let i = 0; i < array.length; i++) {
    hash[array[i]] = true;
  }
  for (let i = 0; i < array.length; i++) {
    let count = 1;
    let left = array[i] - 1;
    let right = array[i] + 1;
    while (hash[left]) {
      count++;
      delete hash[left];
      left--;
    }
    while (hash[right]) {
      count++;
      delete hash[right];
      right++;
    }
    max = Math.max(count, max);
  }
  return max;
}

